const grupos = [
  ['emitida', 'Emitidas', 'Facturas emitidas'],
  ['pagada_parcial', 'Con cobro parcial', 'Facturas con cobro parcial'],
  ['vencida', 'Vencidas', 'Facturas vencidas'],
  ['pagada', 'Pagadas', 'Facturas pagadas'],
];
const resumen = {};
for (const [estado, etiqueta, nodoNombre] of grupos) {
  const lista = $(nodoNombre).first().json.contenido ?? [];
  for (const f of lista) {
    const k = `${etiqueta}|${f.moneda}`;
    resumen[k] = resumen[k] ?? { etiqueta, moneda: f.moneda, cantidad: 0, total: 0, saldo: 0 };
    resumen[k].cantidad += 1;
    resumen[k].total += Number(f.total);
    resumen[k].saldo += Number(f.saldo);
  }
}
const fmt = (n) => n.toFixed(2);
const filas = Object.values(resumen).sort((a, b) => a.etiqueta.localeCompare(b.etiqueta)).map((r) =>
  `<tr><td>${esc(r.etiqueta)}</td><td>${esc(r.moneda)}</td><td style="text-align:right">${r.cantidad}</td><td style="text-align:right">${fmt(r.total)}</td><td style="text-align:right">${fmt(r.saldo)}</td></tr>`).join('');
const cuerpo = filas
  ? `<p>Situacion de facturacion al ${hoy()} (hasta 100 facturas por estado):</p>
<table cellpadding="6" style="border-collapse:collapse"><tr style="background:#f3f4f6"><th>Estado</th><th>Moneda</th><th>Facturas</th><th>Total</th><th>Saldo</th></tr>${filas}</table>`
